    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];
        if (pivot == 0.0) {
            throw std::runtime_error("luFactorize: zero pivot encountered (no pivoting implemented)");
        }

        // Compute multipliers for L column k: A[i,k] /= pivot, for i=k+1..N-1
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Update trailing submatrix: A[i,j] -= A[i,k] * A[k,j]
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            const double lik = A[static_cast<size_t>(i) * N + k];
            const size_t row_i = static_cast<size_t>(i) * N;
            const size_t row_k = k * N;
            for (size_t j = k + 1; j < N; ++j) {
                A[row_i + j] -= lik * A[row_k + j];
            }
